  let pos = 0;
  while ((pos = text.indexOf('_l(', pos)) !== -1) {
    matches.push({ pos, snippet: text.slice(Math.max(0, pos - 50), pos + 150) });
    pos += 3;
    if (matches.length > 5) break;
  }
  return matches;
}));

